98	 */
99	function credentialByProvider(): Map<string, string> {
100	  const docs = readFileSync("docs/agents/reference.md", "utf8");
101	  const map = new Map<string, string>();
102	  for (const line of docs.split(/\r?\n/)) {
103	    const match = /^\|\s*`([a-z][a-z0-9-]*)`\s*\|[^|]*\|\s*`([A-Z][A-Z0-9_]*)`\s*\|/.exec(line);
104	    if (match?.[1] && match[2]) map.set(match[1], match[2]);
105	  }
106	  return map;
107	}
