function readLocalManifest(): { manifest: ReleaseManifest } | { why: string } {
  const path = machineryPath(RELEASE_MANIFEST);
  if (!existsSync(path)) {
    // A tree that cannot say which release it is on cannot be compared with
    // anything, and inventing "up to date" for it would be the failure this whole
    // script exists to prevent. Failing is what `plan_deploy.ts` does with a
    // declaration it could not read, for the same reason.
    return { why: `${path} is missing, so this tree cannot say which release it came from` };
  }
  try {
    const parsed = JSON.parse(readFileSync(path, "utf8")) as Partial<ReleaseManifest>;
    if (typeof parsed.version !== "string" || !parsed.version || !Array.isArray(parsed.files)) {
      return { why: `${path} does not hold a version and a file list` };
    }
    return { manifest: { version: parsed.version, files: parsed.files.map(String) } };
  } catch (error) {
    return { why: `${path} could not be parsed: ${(error as Error).message}` };
  }
}

/** The latest release's tag, or null when it could not be read. */
function latestRelease(): { tag: string; url: string } | null {
  const result = ghRead(
    "api",
    `repos/${UPSTREAM_REPOSITORY}/releases/latest`,
    "--jq",
    "{tag: .tag_name, url: .html_url}",
  );
  if (result.code !== 0) {
    log(`WARN could not read ${UPSTREAM_REPOSITORY}'s latest release: ${result.stderr.trim() || `gh exited ${result.code}`}`);
    return null;
  }
  try {
    const parsed = JSON.parse(result.stdout) as { tag?: string; url?: string };
    if (!parsed.tag) {
      log("WARN the latest release came back with no tag");
      return null;
    }
    return { tag: parsed.tag, url: parsed.url ?? "" };
  } catch {
    log("WARN the latest release was not valid JSON");
    return null;
  }
}

/** The releases the API lists, newest first, or null when they could not be read. */
function releaseNotes(): ReleaseNote[] | null {
  const result = ghRead(
    "api",
    `repos/${UPSTREAM_REPOSITORY}/releases?per_page=100`,
    "--jq",
    '[.[] | {tag: .tag_name, body: (.body // ""), url: .html_url}]',
  );
  if (result.code !== 0) {
    log(`WARN could not read ${UPSTREAM_REPOSITORY}'s releases: ${result.stderr.trim() || `gh exited ${result.code}`}`);
    return null;
  }
  try {
    const parsed = JSON.parse(result.stdout) as unknown;
    if (!Array.isArray(parsed)) {
      log("WARN the release list was not an array");
      return null;
    }
    return parsed
      .filter((entry): entry is ReleaseNote => {
        const note = entry as Partial<ReleaseNote>;
        return typeof note.tag === "string" && note.tag !== "";
      })
      .map((note) => ({ tag: note.tag, body: String(note.body ?? ""), url: String(note.url ?? "") }));
  } catch {
    log("WARN the release list was not valid JSON");
    return null;
  }
}

/**
 * The manifest the latest release shipped, or null.
 *
 * Read from the repository at that tag rather than out of the zip: the asset is a
 * download and an unpack for one JSON file, and the file is the same file.
 */
function upstreamManifest(tag: string): ReleaseManifest | null {
  const result = ghRead(
    "api",
    "-H",
    "Accept: application/vnd.github.raw",
    `repos/${UPSTREAM_REPOSITORY}/contents/${RELEASE_MANIFEST}?ref=${tag}`,
  );
  if (result.code !== 0) {
    log(`WARN could not read ${RELEASE_MANIFEST} at ${tag}: ${result.stderr.trim() || `gh exited ${result.code}`}`);
    return null;
  }
  try {
    const parsed = JSON.parse(result.stdout) as Partial<ReleaseManifest>;
    if (!Array.isArray(parsed.files)) {
      log(`WARN ${RELEASE_MANIFEST} at ${tag} holds no file list`);
      return null;
    }
    return { version: String(parsed.version ?? tag), files: parsed.files.map(String) };
  } catch {
    log(`WARN ${RELEASE_MANIFEST} at ${tag} was not valid JSON`);
    return null;
  }
}

/** The open notice's number, `0` for none, or null when the search could not be made. */
function existingNotice(repo: string): number | null {
  const result = ghRead(
    "issue", "list", "--repo", repo, "--state", "open", "--search", NOTICE_MARKER,
    "--json", "number", "--jq", ".[0].number // 0",
  );
  if (result.code !== 0) {
    log(`WARN could not look for an existing notice in ${repo}: ${result.stderr.trim() || `gh exited ${result.code}`}`);
    return null;
  }
  const number = Number(result.stdout.trim() || "0");
  return Number.isInteger(number) && number > 0 ? number : 0;
}

function main(): void {
  const { values } = parseArgs({
    args: Bun.argv.slice(2),
    options: { repo: { type: "string" } },
  });

  const repo = (values.repo ?? process.env.GITHUB_REPOSITORY ?? "").trim();
  if (!repo) {
    console.error("usage: notify_new_release.ts --repo OWNER/REPO  (or set GITHUB_REPOSITORY)");
    process.exit(2);
  }

  const local = readLocalManifest();
  if (!("manifest" in local)) {
    console.error(`::error::${local.why}. An upgrade cannot be announced for a tree that cannot be compared.`);
    process.exit(1);
  }

  const latest = latestRelease();
  if (latest === null) {
    console.error(
      `::error::could not read ${UPSTREAM_REPOSITORY}'s latest release, so a newer one cannot be ` +
        "announced. A failed read is not an answer of 'up to date'.",
    );
    process.exit(1);
  }

  if (latest.tag === local.manifest.version) {
    log(`${local.manifest.version} is the latest release; nothing to announce`);
    return;
  }

  const notes = releaseNotes();
  const shipped = upstreamManifest(latest.tag);

  const input: NoticeInput = {
    localVersion: local.manifest.version,
    latestVersion: latest.tag,
    window: notes === null ? null : releaseWindow(notes, local.manifest.version),
    windowWhy: `the release list could not be read.`,
    removed: shipped === null ? null : noLongerShipped(shipped, local.manifest.files),
    removedWhy: `${RELEASE_MANIFEST} could not be read at ${latest.tag}.`,
  };

  const title = noticeTitle(input);
  const body = noticeBody(input);

  const existing = existingNotice(repo);
  if (existing === null) {
    // Told apart from "there is none" on purpose: opening a notice on every run
    // because the search failed is how a repository gets one issue per day.
    console.error(`::error::could not search ${repo} for an existing notice, so this run wrote nothing.`);
    process.exit(1);
  }

  const written =
    existing === 0
      ? gh("issue", "create", "--repo", repo, "--title", title, "--body", body)
      : gh("issue", "edit", String(existing), "--repo", repo, "--title", title, "--body", body);
  if (written.code !== 0) {
    console.error(
      `::error::could not ${existing === 0 ? "open" : `update #${existing} in`} ${repo} with the notice for ` +
        `${latest.tag}: ${written.stderr.trim() || `gh exited ${written.code}`}`,
    );
    process.exit(1);
  }

  const where = existing === 0 ? written.stdout.trim() : `#${existing}`;
  log(`announced ${latest.tag} (this tree is on ${local.manifest.version}) at ${where}`);
}

if (import.meta.main) main();
"}

{"content": "import { describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import {
  MAX_RELEASES,
  NOTICE_MARKER,
  releaseWindow,
  UPSTREAM_REPOSITORY,
  type ReleaseNote,
} from "./notify_new_release.ts";
import { removeTemp, runWithFakeGh, scriptPath, type FakeGhRule } from "./testing/harness.ts";

/**
 * The announcement, against the fake `gh`.
 *
 * Two behaviours are the whole of it and both are silent when wrong: a tree that
 * is up to date must write NOTHING (a scheduled run that writes every time is a
 * repository with one issue per day), and a tree that is behind must leave exactly
 * ONE notice behind however many times it runs.
 *
 * The fixtures are a checkout-shaped temp directory — the script reads the
 * manifest off the disk it is run in — and a `gh` that answers the three reads the
 * script makes. A read that fails is a case of its own, because "could not read"
 * and "nothing newer" are the two answers that must never be confused.
 */

/** A `.github/atomaton-release.json`, as a release writes one. */
function checkout(files: string[], version = "v0.1.0"): string {
  const dir = mkdtempSync(join(tmpdir(), "atomaton-new-release-"));
  mkdirSync(join(dir, ".github"), { recursive: true });
  writeFileSync(
    join(dir, ".github", "atomaton-release.json"),
    `${JSON.stringify({ version, files: [".github/atomaton-release.json", ...files] }, null, 2)}\n`,
  );
  return dir;
}

/** The upstream manifest as the contents API returns it, raw. */
function manifestAt(tag: string, files: string[]): string {
  return JSON.stringify({ version: tag, files: [".github/atomaton-release.json", ...files] });
}

/** One release, as the releases list returns it. */
const release = (tag: string, body = `notes for ${tag}`): ReleaseNote => ({
  tag,
  body,
  url: `https://example.test/${tag}`,
});

/**
 * The three reads, as rules.
 *
 * The specific paths come first: `releases/latest` is also a substring of nothing
 * else here, but `contents/` and `releases?per_page` overlap with none — the order
 * is written out anyway because the fake resolves a rule list in order and a
 * later reader adding one should see where it goes.
 */
function reads(
  latest: string,
  options: { notes?: ReleaseNote[]; upstreamFiles?: string[]; notesFail?: boolean; manifestFail?: boolean } = {},
): FakeGhRule[] {
  return [
    {
      match: [`repos/${UPSTREAM_REPOSITORY}/releases/latest`],
      stdout: JSON.stringify({ tag: latest, url: `https://example.test/${latest}` }),
    },
    {
      match: ["contents/.github/atomaton-release.json"],
      ...(options.manifestFail
        ? { code: 1, stdout: "not found" }
        : { stdout: manifestAt(latest, options.upstreamFiles ?? [".github/workflows/atomaton-check.yml"]) }),
    },
    {
      match: ["releases?per_page"],
      ...(options.notesFail
        ? { code: 1, stdout: "boom" }
        : { stdout: JSON.stringify(options.notes ?? [release(latest)]) }),
    },
  ];
}

/** A search answering with the open notice's number, or with none. */
const search = (number: number): FakeGhRule => ({
  match: ["issue", "list"],
  stdout: String(number),
});

/** The `--body` of the one write this run made, or "". */
function writeBody(call: string[]): string {
  const at = call.indexOf("--body");
  return at === -1 ? "" : (call[at + 1] ?? "");
}

describe("when a tree is up to date", () => {
  test("nothing is written at all", () => {
    const dir = checkout([".github/workflows/atomaton-check.yml"], "v0.2.0");
    try {
      const r = runWithFakeGh(scriptPath("notify_new_release.ts"), ["--repo", "owner/repo"], {
        cwd: dir,
        rules: reads("v0.2.0"),
      });
      expect(r.status).toBe(0);
      const wrote = r.ghCalls.filter((call) => call[1] === "create" || call[1] === "edit");
      expect(wrote, "a run that finds nothing newer must not touch the tracker").toEqual([]);
    } finally {
      removeTemp(dir);
    }
  });
});

describe("when a tree is behind", () => {
  const dir = checkout([".github/workflows/atomaton-check.yml", ".github/workflows/atomaton-gone.yml"], "v0.1.0");

  test("one issue is opened, naming both versions", () => {
    try {
      const r = runWithFakeGh(scriptPath("notify_new_release.ts"), ["--repo", "owner/repo"], {
        cwd: dir,
        rules: [
          ...reads("v0.2.0", { notes: [release("v0.2.0"), release("v0.1.5"), release("v0.1.0")] }),
          search(0),
          { match: ["issue", "create"], stdout: "https://example.test/issues/9" },
        ],
      });
      expect(r.status).toBe(0);

      const created = r.ghCalls.filter((call) => call[1] === "create");
      expect(created).toHaveLength(1);
      const [, , , flag, title] = created[0] ?? [];
      expect(flag).toBe("--title");
      expect(title).toContain("v0.2.0");
      expect(title).toContain("v0.1.0");

      const body = writeBody(created[0] ?? []);
      expect(body, "the marker is what keeps this to one notice").toContain(NOTICE_MARKER);
      // Both versions, and the command that takes it.
      expect(body).toContain("v0.1.0");
      expect(body).toContain("v0.2.0");
      expect(body).toContain(`${UPSTREAM_REPOSITORY} -p atomaton-delivery.zip`);
    } finally {
      removeTemp(dir);
    }
  });

  test("the notes carried are the ones between the two, and no others", () => {
    try {
      const r = runWithFakeGh(scriptPath("notify_new_release.ts"), ["--repo", "owner/repo"], {
        cwd: dir,
        rules: [
          ...reads("v0.2.0", { notes: [release("v0.2.0"), release("v0.1.5"), release("v0.1.0"), release("v0.0.9")] }),
          search(0),
          { match: ["issue", "create"] },
        ],
      });
      expect(r.status).toBe(0);
      const body = writeBody(r.ghCalls.find((call) => call[1] === "create") ?? []);
      expect(body).toContain("notes for v0.2.0");
      expect(body).toContain("notes for v0.1.5");
      // Every release already here, and older ones, stay out of it.
      expect(body).not.toContain("notes for v0.1.0");
      expect(body).not.toContain("notes for v0.0.9");
    } finally {
      removeTemp(dir);
    }
  });

  test("a file the latest release no longer ships is listed", () => {
    try {
      const r = runWithFakeGh(scriptPath("notify_new_release.ts"), ["--repo", "owner/repo"], {
        cwd: dir,
        // The release kept atomaton-check.yml and dropped atomaton-gone.yml.
        rules: [...reads("v0.2.0", { upstreamFiles: [".github/workflows/atomaton-check.yml"] }), search(0), { match: ["issue", "create"] }],
      });
      expect(r.status).toBe(0);
      const body = writeBody(r.ghCalls.find((call) => call[1] === "create") ?? []);
      expect(body).toContain("`.github/workflows/atomaton-gone.yml`");
      expect(body, "a file both releases ship is not a deletion").not.toContain("`.github/workflows/atomaton-check.yml`");
      // And the list is a list to read, not one to pipe into rm.
      expect(body).toContain("Read the list rather than acting on it");
    } finally {
      removeTemp(dir);
    }
  });

  test("an open notice is updated rather than a second one opened", () => {
    try {
      const r = runWithFakeGh(scriptPath("notify_new_release.ts"), ["--repo", "owner/repo"], {
        cwd: dir,
        rules: [...reads("v0.2.0"), search(7), { match: ["issue", "edit"] }],
      });
      expect(r.status).toBe(0);
      expect(r.ghCalls.filter((call) => call[1] === "create"), "a second notice buries the repository").toEqual([]);
      const edited = r.ghCalls.filter((call) => call[1] === "edit");
      expect(edited).toHaveLength(1);
      expect(edited[0]).toContain("7");
      expect(writeBody(edited[0] ?? [])).toContain(NOTICE_MARKER);
    } finally {
      removeTemp(dir);
    }
  });
});

describe("a read that fails is not an answer", () => {
  const dir = checkout([".github/workflows/atomaton-check.yml"], "v0.1.0");

  test("a latest release that could not be read fails the run and writes nothing", () => {
    try {
      const r = runWithFakeGh(scriptPath("notify_new_release.ts"), ["--repo", "owner/repo"], {
        cwd: dir,
        // No rule for `releases/latest`, so the read fails.
        rules: [{ match: ["releases?per_page"], stdout: JSON.stringify([release("v0.2.0")]) }],
      });
      expect(r.status).toBe(1);
      expect(r.ghCalls.filter((call) => call[1] === "create" || call[1] === "edit")).toEqual([]);
    } finally {
      removeTemp(dir);
    }
  });

  /**
   * The search failing is told apart from "there is no notice". Collapsing the two
   * opens a fresh issue every time the search blips.
   */
  test("a search that could not be made stops rather than opening a new issue", () => {
    try {
      const r = runWithFakeGh(scriptPath("notify_new_release.ts"), ["--repo", "owner/repo"], {
        cwd: dir,
        rules: [...reads("v0.2.0")],
      });
      expect(r.status).toBe(1);
      expect(r.ghCalls.filter((call) => call[1] === "create")).toEqual([]);
    } finally {
      removeTemp(dir);
    }
  });

  test("a tree with no manifest fails, rather than reading as up to date", () => {
    const empty = mkdtempSync(join(tmpdir(), "atomaton-new-release-bare-"));
    try {
      const r = runWithFakeGh(scriptPath("notify_new_release.ts"), ["--repo", "owner/repo"], {
        cwd: empty,
        rules: reads("v0.2.0"),
      });
      expect(r.status).toBe(1);
      expect(r.stderr).toContain("cannot say which release it came from");
      expect(r.ghCalls.filter((call) => call[1] === "create")).toEqual([]);
    } finally {
      removeTemp(empty);
    }
  });

  /**
   * The notes and the deleted list degrade; the decision does not. A release list
   * that 502s leaves the notice without notes, which a person can still act on,
   * rather than leaving no notice at all.
   */
  test("unreadable notes and an unreadable manifest still leave a notice, saying what is missing", () => {
    try {
      const r = runWithFakeGh(scriptPath("notify_new_release.ts"), ["--repo", "owner/repo"], {
        cwd: dir,
        rules: [...reads("v0.2.0", { notesFail: true, manifestFail: true }), search(0), { match: ["issue", "create"] }],
      });
      expect(r.status).toBe(0);
      const body = writeBody(r.ghCalls.find((call) => call[1] === "create") ?? []);
      expect(body).toContain("Not read:");
      expect(body).toContain("Not computed:");
      expect(body, "the versions are the part that cannot be missing").toContain("v0.2.0");
    } finally {
      removeTemp(dir);
    }
  });
});

describe("which releases are in the window", () => {
  const notes = [release("v0.3.0"), release("v0.2.5"), release("v0.2.0"), release("v0.1.0")];

  test("everything newer than the tree's own version", () => {
    const window = releaseWindow(notes, "v0.2.0");
    expect(window.newer.map((note) => note.tag)).toEqual(["v0.3.0", "v0.2.5"]);
    expect(window.found).toBe(true);
  });

  /** A version the returned page does not reach: the notes are the newest, not all of them. */
  test("a version older than the page says so rather than claiming to be complete", () => {
    const window = releaseWindow(notes, "v0.0.1");
    expect(window.newer).toHaveLength(notes.length);
    expect(window.found).toBe(false);
  });

  test("the list is bounded, and what is left out is counted", () => {
    const many = Array.from({ length: MAX_RELEASES + 5 }, (_, index) => release(`v1.${index}.0`)).reverse();
    const window = releaseWindow([...many, release("v0.0.1")], "v0.0.1");
    expect(window.newer).toHaveLength(MAX_RELEASES);
    expect(window.omitted).toBe(5);
  });
});
